import type { CatalogEntry, Lesson } from '@ss/lesson-engine';
import catalogJson from './catalog.json';
import { CHAPTERS } from './chapters';

/** Generated by `pnpm lessons`; validated in CI. */
export const CATALOG = catalogJson as CatalogEntry[];

const loaders = import.meta.glob<{ default: Lesson }>(['./*.ts', '!./index.ts', '!./chapters.ts']);

export function loadLesson(slug: string): Promise<Lesson> | null {
  const load = loaders[`./${slug}.ts`];
  return load ? load().then((m) => m.default) : null;
}

export interface LessonPlace {
  entry: CatalogEntry;
  /** 1-based chapter number and lesson number across the whole course. */
  chapterNo: number;
  lessonNo: number;
  total: number;
  next: CatalogEntry | undefined;
}

export function placeOf(slug: string): LessonPlace | null {
  const index = CATALOG.findIndex((e) => e.slug === slug);
  const entry = CATALOG[index];
  if (!entry) return null;
  return {
    entry,
    chapterNo: CHAPTERS.findIndex((c) => c.lessons.includes(slug)) + 1,
    lessonNo: index + 1,
    total: CATALOG.length,
    next: CATALOG[index + 1],
  };
}

export { CHAPTERS };
